async function proveGisMapApprovalHistory(repoRoot: string): Promise<Record<string, number>> {
  const root = join(repoRoot, "✏️s/🔌️plugins/🌍️gis/🗿️artifacts/🗺️gismap/💡️inference", "🧫️fixtures", "↩️gis-map-approval-history-v1");
